'use strict';
let session=null,state=null,current=null,csrf='',detailTab='overview',modalSubmit=null,renderToken=0;
const app=document.getElementById('app'),dialog=document.getElementById('dialog');
const roles={enterprise:'需求方工作台',pilot:'飞手工作台',admin:'运营管理台'};
const scenes=['工业巡检','工程测绘','文旅航拍','农业植保','应急巡查'];
const purposeNames={evidence:'业务凭证',payment:'付款凭证',compliance:'合规凭证',deliverable:'成果文件',settlement:'结算凭证',refund:'退款凭证',contract:'合同文件',track:'轨迹文件'};
const kindNames={task:'飞行任务',device:'设备',rental:'租赁订单',job:'招聘岗位',application:'求职申请',ticket:'服务工单',invoice:'开票申请',withdrawal:'对账申请'};
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'¥ '+Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const date=v=>v?new Date(v).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const list=kind=>(state?.records||[]).filter(r=>r.kind===kind);
const mine=r=>r.owner===session.id||r.assigned===session.id;
const status=r=>`<span class="badge ${['completed','settled','resolved','hired','available'].includes(r.status)?'good':['paused','rejected','cancelled'].includes(r.status)?'bad':['pending','payment','cancel_requested','submitted','declared'].includes(r.status)?'warn':'blue'}">${e(r.status_label)}</span>`;
const verifyBadge=v=>`<span class="badge ${v==='approved'?'good':v==='rejected'?'bad':'warn'}">${{approved:'认证已通过',pending:'认证待审核',rejected:'认证未通过'}[v]||'待认证'}</span>`;
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',task:'M6 4h12v17H6z M9 2h6v4H9z M9 10h6 M9 14h6 M9 18h4',plus:'M12 4v16 M4 12h16',flight:'M3 12l18-8-8 18-2-9-8-1z M11 13l10-9',case:'M3 7h18v14H3z M8 7V3h8v4 M3 12h18 M10 12v3h4v-3',device:'M8 8l8 8 M16 8l-8 8 M9 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M21 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M9 18a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M21 18a3 3 0 1 1-6 0 3 3 0 0 1 6 0',wallet:'M3 5h18v15H3z M15 11h6v5h-6z M3 8h18',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 22v-3a8 8 0 0 1 16 0v3',bell:'M5 17h14l-2-3V8a5 5 0 0 0-10 0v6z M9 20h6',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6z M8 12l3 3 5-6',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9a3 3 0 1 1 3 3v3 M12 17v1',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6'};
function icon(k){return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6"><path d="${icons[k]||icons.task}" stroke-linejoin="round" stroke-linecap="round"/></svg>`}
function toast(msg,bad=false){const t=document.getElementById('toast');t.textContent=msg;t.className='show'+(bad?' bad':'');clearTimeout(t.timer);t.timer=setTimeout(()=>t.className='',4500)}
async function api(url,data){const opts={credentials:'same-origin',headers:{'X-CSRFToken':csrf}};if(data!==undefined){opts.method='POST';if(data instanceof FormData)opts.body=data;else{opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data)}}const r=await fetch(url,opts);const d=await r.json().catch(()=>({error:'服务暂不可用，请确认已启动平台服务'}));if(!r.ok)throw Error(d.error||'操作失败，请重试');return d}
function go(path){location.hash='#'+path}
const btn=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const link=(label,path,cls='')=>`<a class="btn ${cls}" href="#${path}">${label}</a>`;
function field(label,name,type='text',value='',required=true,help=''){return `<div class="field"><label class="${required?'required':''}" for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${required?'required':''} ${type==='number'?'step="0.01" min="0"':''}><small>${help}</small></div>`}
function area(label,name,value='',required=true,help=''){return `<div class="field"><label class="${required?'required':''}" for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${required?'required':''}>${e(value)}</textarea><small>${help}</small></div>`}
function select(label,name,options,value='',required=true){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${required?'required':''}>${options.map(x=>{const a=Array.isArray(x)?x:[x,x];return `<option value="${e(a[0])}" ${String(value)===String(a[0])?'selected':''}>${e(a[1])}</option>`}).join('')}</select></div>`}
const check=(label,name,checked=false)=>`<label class="checkline"><input type="checkbox" name="${name}" ${checked?'checked':''}><span>${label}</span></label>`;
function formData(f){const d=Object.fromEntries(new FormData(f));f.querySelectorAll('input[type=checkbox]').forEach(x=>d[x.name]=x.checked);return d}
const empty=(title,desc,action='')=>`<div class="empty"><div class="symbol">${icon('task')}</div><h3>${title}</h3><p>${desc}</p>${action}</div>`;
const card=(title,content,action='')=>`<section class="card"><div class="card-head"><h2>${title}</h2>${action}</div>${content}</section>`;
function publicHead(){return `<header class="public-head"><a href="#home" aria-label="飞链首页"><img class="logo" src="/assets/logo.png" alt="FlyLink 飞链原版商标"></a><nav class="public-nav" aria-label="网站导航"><a href="#new">发布需求</a><a href="#jobs">招聘中心</a><a href="#equipment">设备租赁</a><a href="#hall">飞手接单</a>${link(session?'进入工作台':'登录 / 注册',session?'overview':'login','dark')}</nav></header>`}
function portal(){return `<div class="portal brand-site">${publicHead()}<main><section class="brand-hero"><img class="brand-visual" src="/assets/flight-network.png" alt="无人机与城市协同网络概念视觉" fetchpriority="high"><div class="brand-copy"><p class="brand-label">FLYLINK · 飞链</p><h1>连接低空。<br>成就每一次飞行。</h1><p class="brand-intro">专业飞手、可靠设备、全程协作。<br>让低空服务，触手可及。</p><div class="row">${link('发布作业需求','new','primary')}${link('探索服务','hall','brand-outline')}</div></div><div class="hero-baseline"><span>人 · 设备 · 场景 · 协作</span><small>飞链品牌概念视觉</small></div></section><nav class="service-dock" aria-label="服务快捷入口"><a href="#new"><span>01</span><div><b>飞行服务</b><small>从需求到成果</small></div><i>↗</i></a><a href="#jobs"><span>02</span><div><b>人才招聘</b><small>连接长期合作</small></div><i>↗</i></a><a href="#equipment"><span>03</span><div><b>设备租赁</b><small>装备随任务就位</small></div><i>↗</i></a></nav><section class="brand-section"><div class="editorial-head"><p>为真实的产业需求而来</p><h2>不止于飞行。<br><span>更在于完成。</span></h2><div>从港口到田野，从数据采集到成果交付。<br>让每一次作业，都有清晰的协作路径。</div></div><a class="industry-feature" href="#new?scene=${encodeURIComponent(scenes[0])}"><img src="/assets/port.png" alt="滨海港口无人机巡检概念场景" loading="lazy"><div><small>01 / INDUSTRIAL INSPECTION</small><h3>换一个高度，<br>看清每一处细节。</h3><p>工业巡检 · 设施检查 · 成果交付</p><span>创建巡检需求 ↗</span></div></a><div class="scene-strip">${scenes.map((s,i)=>`<a href="#new?scene=${encodeURIComponent(s)}"><small>0${i+1}</small><b>${s}</b><span>↗</span></a>`).join('')}</div></section><section class="duo-stories"><article class="talent-story"><p class="brand-label">PEOPLE / 专业人才</p><h2>让专长，<br>找到更大的天地。</h2><p>以职业档案连接需求，让合作从了解开始。</p><a href="#jobs" class="story-link">进入招聘中心 ↗</a><div class="talent-art" aria-hidden="true"><span>FLY</span><div class="orbit"></div><b>专业 · 信任 · 协作</b></div></article><article class="gear-story"><img src="/assets/flight-network.png" alt="专业无人机设备概念图" loading="lazy"><div><p class="brand-label">EQUIPMENT / 设备资源</p><h2>好装备。<br>为下一程准备。</h2><p>按任务选择设备，在线管理预约与归还。</p><a href="#equipment" class="story-link">浏览设备资源 ↗</a></div></article></section><section class="brand-section collaboration-section"><div class="editorial-head"><p>一个平台，全程连接</p><h2>每一步，<span>都有回应。</span></h2><div>需求、准备、执行、验收。<br>各方共享进度，合作有据可循。</div></div><div class="journey">${[['01','提出需求','明确场景、预算与交付标准'],['02','准备就绪','匹配人员，核对作业依据'],['03','协同执行','同步进展，留存现场成果'],['04','完成交付','验收、结算登记与评价归档']].map(x=>`<div><small>${x[0]}</small><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div><a class="journey-link" href="#overview">打开协作工作台 <span>↗</span></a></section><section class="brand-closing"><p>FLYLINK</p><h2>让下一次合作，即刻起飞。</h2>${link('开始使用',session?'overview':'register','primary')}</section></main><footer class="brand-footer"><b>FlyLink 飞链</b><span>无人机飞行服务数字化协同平台</span><a href="#support">服务支持 ↗</a><small>概念视觉用于品牌表达。飞行实施以实际适用条件与有效审批依据为准。 · 桌面版 2026.10 R4</small></footer></div>`}
function authPage(register=false){return `${publicHead()}<div class="auth-page"><aside class="auth-story"><div class="eyebrow">CONNECT. COLLABORATE. DELIVER.</div><h1>连接专业。<br>协作更简单。</h1><p>通过统一账户管理任务、人才与设备资源。各方操作保留记录，业务进度实时共享。</p></aside><section class="auth-form"><div><div class="eyebrow">WELCOME TO FLYLINK</div><h1>${register?'创建飞链账户':'欢迎回到飞链'}</h1><p class="muted">${register?'完成注册后，在工作台提交认证资料。':'登录后进入对应身份的业务工作台。'}</p><form data-form="auth"><input type="hidden" name="mode" value="${register?'register':'login'}">${register?field('企业 / 个人名称','name')+select('账户身份','role',[['enterprise','需求方 · 企业 / 单位 / 个人'],['pilot','服务方 · 持证飞手']]):''}${field('账号','username')}${field('密码','password','password','',true,register?'至少10位，请使用独立密码。':'')}${register?`<div class="agreement">平台保存您提交的资料、业务记录和文件，用于核验、履约及争议处理；仅相关参与方和授权运营人员可访问。上传材料需真实且有权提供。正式商业使用前由运营主体完善服务条款与隐私政策。</div>${check('我已阅读并同意上述服务与数据使用约定','agree')}`:''}<div class="form-error" data-error></div><button class="btn primary" style="width:100%">${register?'注册并进入工作台':'登录'}</button></form><p style="margin-top:23px;font-size:13px">${register?'已有账户？ <a class="login-link" href="#login">返回登录</a>':'首次使用？ <a class="login-link" href="#register">创建账户</a>'}</p><small>本地交付的初始账号见软件目录内《首次登录账号.txt》。</small></div></section></div>`}
const navs={enterprise:[['overview','grid','工作概览'],['orders','task','我的任务'],['new','plus','发布需求'],['jobs','case','招聘管理'],['applications','user','应聘与沟通'],['equipment','device','设备租赁'],['rentals','task','我的租赁'],['finance','wallet','交易与发票'],['profile','user','资料与认证'],['notices','bell','消息中心'],['support','help','服务与工单']],pilot:[['overview','grid','工作概览'],['hall','flight','接单大厅'],['orders','task','我的任务'],['jobs','case','招聘中心'],['applications','user','我的投递'],['equipment','device','设备租赁'],['devices','device','我的设备'],['rentals','task','我的租赁'],['finance','wallet','收益与对账'],['profile','user','职业档案与认证'],['notices','bell','消息中心'],['support','help','服务与工单']],admin:[['overview','grid','运营概览'],['orders','task','订单监管'],['compliance','shield','合规与异常'],['users','user','用户资质审核'],['devices','device','设备管理'],['rentals','task','租赁监管'],['jobs','case','招聘管理'],['applications','user','招聘进度'],['finance','wallet','交易与结算'],['support','help','服务工单'],['notices','bell','消息中心'],['settings','settings','平台设置']]};
function shell(content,route){const items=navs[session.role];const unread=state.notices.filter(n=>!n.read).length;const label=route==='detail'?'业务详情':items.find(x=>x[0]===route)?.[2]||'工作台';return `<div class="shell"><aside class="sidebar" id="sidebar"><a class="side-brand" href="#home"><img src="/assets/logo.png" class="logo" alt="FlyLink 飞链"></a><div class="side-role">${icon('shield')}<strong>${roles[session.role]}</strong></div><nav class="side-nav" aria-label="业务导航"><div class="nav-group">WORKSPACE / 业务空间</div>${items.map((x,i)=>`${i===8?'<div class="nav-group">ACCOUNT / 账户与服务</div>':''}<a href="#${x[0]}" class="${route===x[0]?'active':''}">${icon(x[1])}<span>${x[2]}</span></a>`).join('')}</nav><div class="side-bottom">飞链 · 连接每一次专业飞行<br><a href="#home">返回网站首页</a></div></aside><div class="main-area"><header class="topbar"><div class="row"><button class="mobile-menu" data-action="menu" aria-label="切换导航">☰</button><div class="breadcrumbs">飞链协作平台 <b>/ &nbsp; ${label}</b></div></div><div class="row"><a class="bell" href="#notices" aria-label="消息中心">${icon('bell')}${unread?`<b>${unread>99?'99+':unread}</b>`:''}</a><div class="avatar">${e((session.data.name||session.username).slice(0,1))}</div><a class="top-user" href="#profile" title="资料与账户安全">${e(session.data.name||session.username)}</a><button class="link" data-action="logout" style="font-size:12px;color:#7e8c9b">退出</button></div></header><main class="content">${content}<div class="footer-note">FlyLink 飞链 · 业务记录仅对参与方与授权运营人员开放</div></main></div></div>`}
function pageHead(title,desc,actions='',eyebrow='FLYLINK WORKSPACE'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="row wrap">${actions}</div></div>`}
function stats(items){return `<div class="stats">${items.map(x=>`<div class="stat"><div class="stat-label">${x[0]}</div><div class="stat-value">${x[1]}</div><div class="stat-note">${x[2]}</div></div>`).join('')}</div>`}
function taskTable(records,compact=false){if(!records.length)return empty('暂无任务记录','完成认证后发布需求，或前往接单大厅查看符合资质的任务。',session.role==='enterprise'?link('发布需求','new','primary'):session.role==='pilot'?link('前往接单大厅','hall','primary'):'');return `<div class="table-wrap"><table><thead><tr><th>任务 / 编号</th><th>执行时间</th><th>项目预算</th><th>状态</th><th></th></tr></thead><tbody>${records.map(r=>`<tr data-filter="${e((r.data.title||'')+' '+r.number+' '+r.data.scene)}" data-status="${r.status}"><td><a class="table-title" href="#detail/${r.id}">${e(r.data.title)}</a><span class="sub">${e(r.number)} · ${e(r.data.scene)}${r.data.urgent?' · 加急':''}</span></td><td>${date(r.data.execute_time)}<span class="sub">${e(r.data.location)}</span></td><td class="money">${money(r.data.budget)}</td><td>${status(r)}</td><td>${link('查看','detail/'+r.id,'small')}</td></tr>`).join('')}</tbody></table></div>`}
function overview(){const tasks=list('task').filter(r=>session.role==='admin'||mine(r));const active=tasks.filter(r=>!['completed','cancelled','rejected'].includes(r.status));const todos=tasks.filter(r=>session.role==='admin'?['pending','declared','settlement','paused','cancel_requested'].includes(r.status):session.role==='enterprise'?['submitted','settled','rejected'].includes(r.status):['accepted','ready','rework','settled'].includes(r.status));const earned=tasks.reduce((s,r)=>s+Number(r.data.income||0),0);const recent=tasks.slice(0,5);return pageHead(`${session.data.name||session.username}，欢迎回来`,'从待办开始，掌握项目、资源与交付的最新进展。',`${btn('刷新数据','refresh')}${session.role==='enterprise'?link('发布新需求','new','primary'):session.role==='pilot'?link('浏览可接任务','hall','primary'):link('处理合规审核','compliance','primary')}`,'OVERVIEW / 工作概览')+stats([['进行中任务',active.length,'根据实际业务记录统计'],['当前待办',todos.length,'等待您处理的业务环节'],[session.role==='pilot'?'已登记收入':'待审核资料',session.role==='pilot'?money(earned):session.role==='admin'?state.people.filter(p=>p.verification==='pending').length:session.verification==='approved'?'0':'1',session.role==='pilot'?'基于已核对的结算记录':'资料完善后进入运营审核'],['已完成任务',tasks.filter(r=>r.status==='completed').length,'双方评价完成并已归档']])+`${session.role!=='admin'&&session.verification!=='approved'?`<div class="notice warn" style="margin-bottom:23px"><div class="row between wrap"><span>账户尚未通过认证。请完善${session.role==='pilot'?'证照、保险和授权场景':'主体与联系人'}资料并上传凭证。</span>${link('去完善资料','profile','small')}</div></div>`:''}<div class="dashboard-grid"><div class="stack">${card('任务进展',taskTable(recent,true),link('全部任务','orders','small'))}${card('需要您处理',todos.length?todos.slice(0,5).map(r=>`<a class="todo" href="#detail/${r.id}"><span class="circle">${icon('task')}</span><div><b>${e(r.data.title)}</b><p>${e(r.status_label)} · ${e(r.number)}</p></div>${status(r)}</a>`).join(''):empty('当前没有待处理事项','业务状态变化后，待办会出现在这里。'))}</div><div class="stack"><section class="card welcome pad"><div class="eyebrow">YOUR NEXT STEP</div><h2>${session.role==='enterprise'?'从一份明确的需求开始':session.role==='pilot'?'让您的专业能力被看见':'把每个关键环节核实清楚'}</h2><p>${session.role==='enterprise'?'填写作业地点、时间和验收标准，平台将据此核对资源与执行条件。':session.role==='pilot'?'完善职业档案与资质材料，符合授权的任务才会进入您的接单大厅。':'先核验主体资质，再检查任务依据。异常、付款和结算均保留处理记录。'}</p><div class="row">${link(session.role==='admin'?'查看待审核用户':'管理个人资料',session.role==='admin'?'users':'profile','light')}</div></section>${card('工作入口',navs[session.role].filter(x=>['new','hall','equipment','jobs','support'].includes(x[0])).map(x=>`<a class="todo" href="#${x[0]}"><span class="circle">${icon(x[1])}</span><div><b>${x[2]}</b></div><span class="muted">›</span></a>`).join(''))}${card('最近通知',state.notices.slice(0,3).map(n=>`<a class="todo" href="#${n.record_id?'detail/'+n.record_id:'notices'}"><div><p style="color:#4c6479">${e(n.text)}</p><small>${date(n.created_at)}</small></div></a>`).join('')||empty('暂无新消息','业务变更会自动通知参与方。'))}</div></div>`}
function toolbar(records,placeholder='搜索标题、编号或场景'){const statuses=[...new Map(records.map(r=>[r.status,r.status_label])).entries()];return `<div class="toolbar"><input id="search" type="search" placeholder="${placeholder}" aria-label="搜索记录"><select id="statusFilter" aria-label="按状态筛选"><option value="">全部状态</option>${statuses.map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><span class="result-count">共 ${records.length} 条记录</span></div>`}
function ordersPage(mode){let rows=list('task').filter(r=>session.role==='admin'||(mode==='hall'?r.status==='open':mine(r)));if(mode==='compliance')rows=rows.filter(r=>!['completed','cancelled'].includes(r.status));return pageHead(mode==='hall'?'接单大厅':mode==='compliance'?'合规与异常处理':'飞行任务',mode==='hall'?'展示符合您认证、授权场景与接单状态的任务；接单时再次核验作业条件。':mode==='compliance'?'核对文件依据、设备登记与近期天气记录，处理异常任务。':'管理从需求提交到成果验收、结算归档的完整过程。',session.role==='enterprise'?link('发布新需求','new','primary'):`${btn('刷新列表','refresh')}${session.role==='pilot'?btn(session.data.online==='idle'?'接单状态：在线':'设置接单状态','online','primary'):''}`)+`<section class="card">${toolbar(rows)}${taskTable(rows)}</section>`}
function newTask(){if(session.role!=='enterprise')return pageHead('发布需求','此功能面向需求方账户。')+empty('请使用需求方账户','飞手可前往接单大厅承接任务；运营人员可在订单监管中处理业务。',link('返回工作台','overview','primary'));const scene=new URLSearchParams(location.hash.split('?')[1]||'').get('scene')||scenes[0];return pageHead('发布作业需求','把目标、现场条件和验收标准说清楚，协作从这里开始。',link('返回任务列表','orders'))+`<div class="detail-layout"><form data-form="new-task" class="card"><section class="form-section"><h3><span>1</span>服务与场景</h3><div class="form-grid">${select('服务方式','service',[['bundle','飞手 + 无人机一体化服务'],['pilot','仅飞手服务（需求方提供设备）']])}${select('作业场景','scene',scenes,scene)}<div class="full">${field('任务标题','title','text','',true,'例如：某厂区屋顶红外巡检')}</div></div></section><section class="form-section"><h3><span>2</span>作业信息</h3><div class="form-grid"><div class="full">${field('详细作业地点','location')}</div>${field('纬度','lat','number','',true,'范围 -90 至 90')}${field('经度','lng','number','',true,'范围 -180 至 180')}${field('计划执行时间','execute_time','datetime-local')}${field('面积 / 时长 / 点位数量','quantity')}${select('空域情况','airspace_type',[['unknown','待核实'],['controlled','需核实管制及申报要求'],['known','已有相关依据，提交后上传']])}${select('执照要求','license',['CAAC-视距内','CAAC-超视距'])}<div class="full">${field('设备与专项能力要求','device_requirement','text','',false)}</div></div></section><section class="form-section"><h3><span>3</span>交付与预算</h3>${area('作业说明','requirements')}${area('验收标准','acceptance',scene==='工业巡检'?'按约定点位完成巡检；影像清晰可用；提交带点位说明的巡检报告。':'请明确交付内容、覆盖范围、质量标准及交付时限。')}<div class="form-grid">${field('项目总预算（元）','budget','number')}${field('当前平台服务费率','fee_preview','text',(state.config.rate||0)+'%',false,'下单时锁定费率；在飞手接单前展示。')}</div>${check('加急任务（加急不压缩审批与安全检查时间）','urgent')}<div class="notice">现场图纸与资料可在任务创建后进入“文件与成果”上传。空域和天气条件由运营依据有效材料核实，未知条件不会自动通过。</div></section><div class="form-footer"><span class="muted">${verifyBadge(session.verification)} · 提交后进入运营审核</span><button class="btn primary">提交作业需求</button></div><div class="form-error" data-error></div></form><aside class="stack"><section class="card pad form-side"><div class="eyebrow">SERVICE GUIDE</div><h2>一份完整的需求</h2><p class="muted">清晰的标准有助于飞手判断能力、设备和执行条件，也让成果验收有据可依。</p>${['明确作业区域与实际范围','约定原始素材与报告格式','提供现场限制与联系人信息','在开始前完成全部条件核验'].map((x,i)=>`<div class="data-line"><small>0${i+1}</small><strong>${x}</strong></div>`).join('')}<div style="margin-top:22px">${link('只需要设备？前往租赁','equipment','small')}</div></section></aside></div>`}
function listingPage(type){const devices=type==='equipment'||type==='devices';let records=list(devices?'device':type==='applications'?'application':'job');if(type==='devices'&&session.role!=='admin')records=records.filter(r=>r.owner===session.id);if(type==='equipment')records=records.filter(r=>r.status==='available');if(type==='jobs'&&session.role==='enterprise')records=records.filter(r=>r.owner===session.id);const title={equipment:'无人机设备租赁',devices:session.role==='admin'?'设备审核与管理':'我的设备',jobs:session.role==='enterprise'?'招聘管理':'招聘中心',applications:session.role==='enterprise'?'应聘与沟通':'投递与招聘进度'}[type];const createBtn=type==='devices'?btn('登记设备','new-device','primary'):type==='jobs'&&session.role==='enterprise'?btn('发布岗位','new-job','primary'):'';return pageHead(title,devices?'查看设备信息、可租日期与维保凭证，完成从预约到归还的协作。':'把职业能力、沟通记录与招聘进度放在一起。',createBtn)+`<section class="card" style="margin-bottom:22px">${toolbar(records,'搜索名称或城市')}</section>${records.length?`<div class="cards">${records.map(r=>`<article class="card listing" data-filter="${e(r.data.title+' '+(r.data.city||''))}" data-status="${r.status}">${devices?`<div class="device-art">${icon('device')}<small>${e(r.data.model||'设备档案')}</small></div>`:''}<div class="listing-top" style="margin-top:15px"><span class="eyebrow" style="margin:0">${devices?'EQUIPMENT':type==='applications'?'APPLICATION':'CAREERS'}</span>${status(r)}</div><h3>${e(r.data.title)}</h3><p>${e(r.data.city||r.owner_name)} · ${devices?e(r.data.model):e(r.data.job_type||r.assigned_name||'招聘协作')}</p><p>${e((r.data.description||r.data.cover||'查看详情，了解要求与当前进度。').slice(0,85))}</p><div class="card-actions"><span class="money">${devices?money(r.data.daily_price)+'<small style="font-size:11px;font-weight:400"> / 天</small>':r.data.salary_min?money(r.data.salary_min)+'<small style="font-size:11px;font-weight:400"> 起 / 月</small>':''}</span>${link('查看详情','detail/'+r.id,'small')}</div></article>`).join('')}</div>`:card('业务记录',empty('暂无'+(devices?'设备':'记录'),devices?'上架的设备需经资料审核后显示在租赁市场。':'发布岗位或提交申请后，相关进度会在这里显示。',createBtn))}`}
function genericTable(records){if(!records.length)return empty('暂无业务记录','创建业务后可在这里查看进度、文件和沟通记录。');return `<div class="table-wrap"><table><thead><tr><th>标题 / 编号</th><th>业务类型</th><th>创建时间</th><th>状态</th><th></th></tr></thead><tbody>${records.map(r=>`<tr data-filter="${e(r.data.title+' '+r.number)}" data-status="${r.status}"><td><a class="table-title" href="#detail/${r.id}">${e(r.data.title)}</a><span class="sub">${e(r.number)} · ${e(r.owner_name)}</span></td><td>${kindNames[r.kind]}</td><td>${date(r.created_at)}</td><td>${status(r)}</td><td>${link('查看','detail/'+r.id,'small')}</td></tr>`).join('')}</tbody></table></div>`}
function rentals(){const rows=list('rental');return pageHead('租赁订单','查看租期、付款核对、归还验机与押金处理。',link('浏览设备','equipment','primary'))+card('租赁记录',toolbar(rows)+genericTable(rows))}
function finance(){const tasks=list('task').filter(r=>session.role==='admin'||mine(r));const funds=tasks.filter(r=>r.data.payment_received&&!r.data.refund_ref).reduce((s,r)=>s+Number(r.data.budget),0);const earned=tasks.reduce((s,r)=>s+Number(r.data.income||0),0);const pending=tasks.filter(r=>r.status==='settlement');const applications=state.records.filter(r=>['invoice','withdrawal'].includes(r.kind));return pageHead(session.role==='pilot'?'收益与对账':'交易与结算','收款、退款与结算均依据实际凭证登记；金额不会通过网页自动划转。',`<a class="btn" href="/api/export">导出业务对账单</a>`)+stats([['已核对收款',money(funds),'以已登记付款凭证为依据'],['已登记飞手收入',money(earned),'扣除订单锁定的平台服务费'],['等待结算',pending.length,'验收通过后等待财务处理'],['开票 / 对账申请',applications.filter(r=>r.status!=='resolved').length,'待处理的服务申请']])+card('任务收付款记录',taskTable(tasks))+`<div class="section-gap">${card('开票与对账申请',genericTable(applications))}</div>`}
function filesHTML(files){return files.length?files.map(f=>`<div class="file-row"><div class="file-icon">${e(f.name.split('.').pop().toUpperCase())}</div><div class="file-info"><b>${e(f.name)}</b><small>${purposeNames[f.purpose]||'认证材料'} · ${(f.size/1024).toFixed(1)} KB · ${date(f.created_at)}</small><small title="${e(f.sha256)}">SHA-256 ${e((f.sha256||'').slice(0,22))}…</small></div><a class="btn small" href="/api/files/${f.id}">下载</a></div>`).join(''):empty('暂无文件','上传后可供相关参与方查看和下载。')}
function uploadForm(record='',allowAll=true){return `<form data-form="upload" class="drop"><input type="hidden" name="record" value="${record}"><p>上传后保存原始文件与校验值，支持 PDF、图片、文档、视频、ZIP、KML；单文件不超过20 MB。</p><div class="form-grid">${allowAll?select('文件用途','purpose',Object.entries(purposeNames)):'<input type="hidden" name="purpose" value="evidence">'}<div class="field"><label for="upload-file">选择文件</label><input id="upload-file" name="file" type="file" required></div></div><div class="form-error" data-error></div><button class="btn primary small">上传并保存</button></form>`}
async function profilePage(){const f=await api('/api/users/'+session.id+'/files');const d=session.data;return pageHead(session.role==='pilot'?'职业档案与认证':'主体资料与认证','信息变更后重新审核；认证文件仅本人及运营审核人员可访问。',verifyBadge(session.verification))+`<div class="detail-layout"><div class="stack"><form data-form="profile" class="card"><div class="card-head"><h2>基本资料</h2></div><div class="pad"><div class="form-grid">${field('企业 / 个人名称','name','text',d.name)}${field('所在城市','city','text',d.city)}${field('联系人与电话','contact','text',d.contact)}${session.role==='enterprise'?field('统一社会信用代码 / 主体编号','company_no','text',d.company_no):field('实操年限','experience','number',d.experience||0)}</div>${session.role==='pilot'?`<div class="form-grid">${select('执照等级','license',['CAAC-视距内','CAAC-超视距'],d.license)}${field('执照有效期','license_expiry','date',d.license_expiry)}${field('保险单号','insurance_no','text',d.insurance_no)}${field('保险有效期','insurance_expiry','date',d.insurance_expiry)}${field('可承接机型','device','text',d.device)}${field('航空器登记编号','registration','text',d.registration)}</div><div class="field"><label>申请授权的作业场景</label><div class="checks">${scenes.map(s=>`<label class="checkline"><input type="checkbox" name="skill" value="${s}" ${(d.skills||[]).includes(s)?'checked':''}>${s}</label>`).join('')}</div></div>${check('我当前处于带教期，尚不申请独立接单权限','trainee',d.trainee)}${area('代表项目与经验','projects',d.projects,false)}${field('教育与培训经历','education','text',d.education,false)}`:''}${area('简介与补充说明','bio',d.bio,false)}${d.review_reason?`<div class="notice">最近审核意见：${e(d.review_reason)}</div>`:''}<div class="form-error" data-error></div></div><div class="form-footer"><span class="muted">请先上传相关材料，再提交审核。</span><button class="btn primary">保存并提交审核</button></div></form>${card('认证材料',`<div class="pad">${filesHTML(f.files)}${uploadForm('',false)}</div>`)}</div><aside class="stack">${card('账户安全',`<div class="pad"><p class="muted">账号：${e(session.username)}</p>${btn('修改登录密码','password')}</div>`)}${session.role==='pilot'?card('接单状态',`<div class="pad"><p>当前状态：${{idle:'在线接单',busy:'忙碌中',offline:'休息中'}[d.online]||'休息中'}</p>${btn('调整接单状态','online','primary')}</div>`):''}<section class="card pad"><div class="eyebrow">VERIFICATION</div><h3>让资料可被核验</h3><p class="muted">请提交有效、清晰的主体证明。飞手还需提供执照、保险、航空器登记和项目经历证明。认证通过并取得场景授权后，才可承接相关任务。</p></section></aside></div>`}
function users(){const people=state.people.filter(p=>p.role!=='admin');return pageHead('用户资质审核','核对主体、证照、保险与任务范围，保留审核意见。')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>用户 / 主体</th><th>身份</th><th>申请场景</th><th>认证状态</th><th></th></tr></thead><tbody>${people.map(p=>`<tr><td>${e(p.data.name||p.username)}<span class="sub">${e(p.username)} · ${e(p.data.city)}</span></td><td>${p.role==='pilot'?'飞手':'需求方'}${!p.active?'<span class="badge bad">已停用</span>':''}</td><td>${e((p.data.skills||[]).join(' / ')||'—')}</td><td>${verifyBadge(p.verification)}</td><td>${btn('查看与审核','review-user','small',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>${!people.length?empty('暂无注册用户','需求方与飞手注册后进入此审核列表。'):''}</section>`}
function noticesPage(){return pageHead('消息中心','接收与您有关的任务、资料、租赁及服务进度。',btn('全部标为已读','read-all'))+card('业务通知',state.notices.length?state.notices.map(n=>`<div class="notification ${n.read?'':'unread'}"><span class="badge ${n.read?'':'blue'}">${n.read?'已读':'未读'}</span><div class="content-text"><p>${e(n.text)}</p><small>${date(n.created_at)}</small></div>${btn(n.record_id?'查看业务':'标为已读','notice','small',`data-id="${n.id}" data-record="${n.record_id||''}"`)}</div>`).join(''):empty('暂无消息','相关业务有进展时会自动通知您。'))}
function support(){const rows=state.records.filter(r=>['ticket','invoice','withdrawal'].includes(r.kind));return pageHead('服务与工单','提交业务咨询、纠纷或售后问题，记录沟通与处理结果。',btn('创建服务工单','new-ticket','primary'))+card('服务记录',toolbar(rows)+genericTable(rows))}
function settingsPage(){return pageHead('平台设置','配置适用于新订单的规则；历史订单保留创建时的费率。')+`<div class="grid2"><form data-form="config" class="card"><div class="card-head"><h2>服务费配置</h2></div><div class="pad">${field('新订单基础服务费率（%）','rate','number',state.config.rate,true,'范围0%—20%，在发单和接单前展示。')}<div class="form-error" data-error></div><button class="btn primary">保存配置</button></div></form>${card('作业条件校验',`<div class="pad"><p>证照、保险、设备、空域和天气五项检查，在接单和开始作业时由服务端执行。</p><div class="notice">任何角色都不能通过页面关闭这些检查。天气核对记录超过3小时后需要重新确认。</div></div>`)}</div>`}
function timeline(r){const phases=['发单审核','匹配接单','飞行准备','作业执行','验收结算','评价归档'];const map={pending:0,rejected:0,open:1,accepted:2,declared:2,ready:2,working:3,rework:3,submitted:4,settlement:4,settled:5,completed:5};let i=map[r.status]??-1;return `<div class="timeline">${phases.map((p,n)=>`<div class="phase ${n<i?'done':n===i?'active':''}"><span>${n<i?'✓':n+1}</span>${p}</div>`).join('')}</div>`}
function detailMeta(r){const d=r.data;let pairs=r.kind==='task'?[['作业场景',d.scene],['服务方式',d.service==='bundle'?'飞手 + 无人机':'仅飞手'],['执行时间',date(d.execute_time)],['面积 / 时长',d.quantity],['作业地点',d.location],['坐标',`${d.lat}, ${d.lng}`],['需求方',r.owner_name],['承接飞手',r.assigned_name||'尚未接单'],['执照要求',d.license],['设备要求',d.device_requirement||'详见需求说明'],['作业说明',d.requirements],['验收标准',d.acceptance]]:r.kind==='device'?[['设备型号',d.model],['所在城市',d.city],['登记编号',d.registration],['设备参数',d.specs],['配件清单',d.accessories],['日租金',money(d.daily_price)],['押金',money(d.deposit)],['设备说明',d.description]]:r.kind==='job'?[['所在城市',d.city],['岗位类型',d.job_type],['薪资范围',money(d.salary_min)+' — '+money(d.salary_max)],['执照要求',d.license],['工作内容',d.description]]:r.kind==='rental'?[['租赁设备',d.title],['租期',d.start+' 至 '+d.end],['租赁天数',d.days+' 天'],['交付方式',d.delivery],['交付地址',d.address],['租金',money(d.rent)],['押金',money(d.deposit)],['保险依据',d.insurance_ref||'待上传核验'],['归还说明',d.return_note],['验机结果',d.inspection],['押金退还',d.refund?money(d.refund):'待核对']]:r.kind==='application'?[['应聘者',r.owner_name],['招聘方',r.assigned_name],['应聘说明',d.cover],['面试安排',d.interview],['录用说明',d.offer],['双方确认',Object.keys(d.signatures||{}).length+' / 2'],['处理意见',d.reason]]:[['发起人',r.owner_name],['类型',d.category||kindNames[r.kind]],['问题 / 申请说明',d.description],['处理结果',d.result||'等待处理']];return `<dl class="detail-meta">${pairs.filter(x=>x[1]!==undefined&&x[1]!=='').map(([k,v])=>`<div><dt>${k}</dt><dd>${e(v)}</dd></div>`).join('')}</dl>`}
function recordActions(r){const u=session,owner=r.owner===u.id,worker=r.assigned===u.id,op=u.role==='admin',s=r.status,d=r.data;let a=[];const add=(label,action,cls='primary')=>a.push(btn(label,'record-action',cls,`data-do="${action}"`));if(r.kind==='task'){
 if(op&&s==='pending'){add('审核需求','review')};if(owner&&s==='rejected')add('补充说明并重新提交','resubmit');if(op&&!['completed','cancelled'].includes(s))add('核对作业条件','gates','');if(u.role==='pilot'&&s==='open')add('确认条件并接单','claim');if(worker&&['accepted','declared'].includes(s))add('提交飞行计划','plan');if(op&&s==='declared')add('复核飞行准备','release');if(op&&!d.payment_received&&!['cancelled','completed'].includes(s))add('核对实际收款','payment','');if(worker&&s==='ready')add('现场检查并开始作业','start');if(worker&&['working','rework'].includes(s))add('提交成果供验收','submit');if(owner&&s==='submitted'){add('验收通过','accept');add('退回整改','rework','')};if(op&&s==='settlement')add('登记实际结算','settle');if((owner||worker)&&['settled','completed'].includes(s)&&!d.reviews?.[String(u.id)])add('提交履约评价','review_service');if((owner||worker||op)&&['ready','working','accepted','declared'].includes(s))add('异常上报并中止','pause','danger');if(op&&s==='paused')add('复核并恢复任务','resume');if(owner&&['pending','open','accepted','declared','ready'].includes(s))add('申请改期','reschedule','');if(owner&&['pending','rejected','open','accepted','declared','ready','paused'].includes(s))add('申请取消','cancel','');if(op&&s==='cancel_requested')add('处理取消与退款','cancel_confirm');if(owner&&['settled','completed'].includes(s))add('申请开票','invoice','');if(worker&&['settled','completed'].includes(s))add('申请结算对账','withdrawal','');
 }else if(r.kind==='device'){if(op&&s==='pending')add('审核设备资料','review');if((owner||op)&&['available','unavailable'].includes(s))add(s==='available'?'暂停出租':'恢复上架','toggle','');if(!owner&&s==='available')add('选择租期并预约','rent')}
 else if(r.kind==='rental'){if(op&&s==='payment')add('核对租金与保险','payment');if(owner&&s==='renting')add('申请归还','return');if(op&&s==='returning')add('验机与押金结清','inspect');if(owner&&s==='payment')add('取消未付款预约','cancel','')}
 else if(r.kind==='job'){if(op&&s==='pending')add('审核招聘岗位','review');if((owner||op)&&s==='open')add('关闭岗位','close','');if(u.role==='pilot'&&s==='open')add('投递职业档案','apply')}
 else if(r.kind==='application'){if(worker&&['applied','interview'].includes(s)){add('发送面试安排','interview');add('提交录用与合同','offer')};if((owner||worker)&&s==='offered'&&!d.signatures?.[String(u.id)])add('确认合同内容','sign');if(worker&&s==='offered')add('确认入职','hire');if(worker&&!['hired','rejected'].includes(s))add('结束本次申请','reject','')}
 else if(op){if(['pending','processing'].includes(s)){add('记录处理进展','process','');add('完成处理','resolve')}}
 return a.length?a.join(''):`<div class="notice">${['completed','cancelled','settled','hired','resolved'].includes(s)?'当前环节已完成，可查看业务记录与文件。':'当前等待相关参与方处理。您可以在沟通区补充说明。'}</div>`}
function detailBody(){const {record:r,files,messages,events,gates:g,candidates}=current;const d=r.data;const participant=session.role==='admin'||r.owner===session.id||r.assigned===session.id;if(detailTab==='files')return `<div class="pad">${filesHTML(files)}${participant&&!['completed','cancelled'].includes(r.status)?uploadForm(r.id):''}</div>`;if(detailTab==='chat')return `<div class="pad"><div class="chat-list">${messages.length?messages.map(m=>`<div class="chat-bubble ${m.sender_id===session.id?'mine':''}"><small>${e(m.sender__username)} · ${date(m.created_at)}</small>${e(m.text)}</div>`).join(''):empty('开始业务沟通','围绕需求、交付或安排交换意见，消息会保留在本业务记录中。')}</div>${participant?`<form data-form="chat">${area('发送消息','text','',true,'请勿发送与本次业务无关的敏感信息。')}<div class="form-error" data-error></div><button class="btn primary">发送消息</button></form>`:''}</div>`;if(detailTab==='audit')return `<div class="pad">${events.length?events.map(v=>`<div class="event"><b>${e(v.action)}</b><p>${e(v.detail.note||v.detail.name||'')}</p><small>${e(v.user__username)} · ${date(v.created_at)}</small></div>`).join(''):empty('尚无操作记录','业务操作将按时间顺序保留。')}</div>`;if(detailTab==='compliance')return `<div class="pad"><div class="notice">每项条件必须有有效依据。下列状态由服务端校验；空域依据由运营人工录入，不等于系统签发许可。</div>${g.map(x=>`<div class="gate ${x.ok?'pass':''}"><div class="gate-icon">${x.ok?'✓':'!'}</div><div><b>${x.label}</b><p>${e(x.detail)}</p></div><span class="badge ${x.ok?'good':'warn'}" style="margin-left:auto">${x.ok?'已通过':'待核验'}</span></div>`).join('')}${d.plan?`<h3 class="section-gap">飞行计划</h3><p style="white-space:pre-wrap">${e(d.plan)}</p>`:'<p class="muted section-gap">承接飞手尚未提交飞行计划。</p>'}${d.release_note?`<div class="notice">准备复核：${e(d.release_note)}</div>`:''}</div>`;if(detailTab==='candidates')return `<div class="pad"><div class="notice">按已审核资质、授权场景、有效期与在线状态筛选。仅展示符合条件的飞手，不生成未经验证的“AI匹配分”。</div>${candidates.length?candidates.map(p=>`<div class="mini-person"><div class="avatar">${e((p.data.name||p.username).slice(0,1))}</div><div style="flex:1"><h3 style="margin:0">${e(p.data.name||p.username)}</h3><p>${e(p.data.license)} · ${e(p.data.city)} · ${e(p.data.experience||0)}年经验</p><p>${e((p.data.skills||[]).join(' / '))}</p><p>${e(p.data.bio||'')}</p>${r.status==='open'?btn('发送任务邀约','invite','small',`data-id="${p.id}"`):''}</div></div>`).join(''):empty('暂未找到符合条件的飞手','请确认飞手已通过认证、处于在线接单状态且具有对应场景授权。')}</div>`;
return `<div class="pad">${detailMeta(r)}${d.report?`<h3 class="section-gap">成果说明</h3><p style="white-space:pre-wrap">${e(d.report)}</p>`:''}${['review_note','rework_note','incident','cancel_reason','cancel_result','acceptance_note'].filter(k=>d[k]).map(k=>`<div class="notice ${k==='incident'?'warn':''} section-gap"><b>${{review_note:'审核意见',rework_note:'整改要求',incident:'异常记录',cancel_reason:'取消原因',cancel_result:'取消结果',acceptance_note:'验收意见'}[k]}</b><br>${e(d[k])}</div>`).join('')}${Object.keys(d.reviews||{}).length?`<h3 class="section-gap">履约评价</h3>${Object.values(d.reviews).map(v=>`<div class="notice section-gap">${'★'.repeat(v.rating)}<br>${e(v.text)}</div>`).join('')}`:''}</div>`}
function detailPage(){const r=current.record;const d=r.data;const participant=session.role==='admin'||r.owner===session.id||r.assigned===session.id;const tabs=[['overview','业务信息'],...(r.kind==='task'?[['compliance','作业条件'],...((r.owner===session.id||session.role==='admin')?[['candidates','可用飞手']]:[])]:[]),...(participant?[['files','文件与成果'],['chat','业务沟通'],['audit','操作记录']]:[])];if(!tabs.some(x=>x[0]===detailTab))detailTab='overview';return pageHead(e(d.title),`${r.number} · ${kindNames[r.kind]} · ${date(r.created_at)}`,`${status(r)}${btn('刷新进度','refresh','small')}${participant?`<a class="btn small" href="/api/records/${r.id}/export">导出业务档案</a>`:''}`,'BUSINESS RECORD / 业务详情')+`<div class="detail-layout"><div class="stack">${r.kind==='task'?`<section class="card">${timeline(r)}</section>`:''}<section class="card"><nav class="tabs" aria-label="详情分类">${tabs.map(([id,label])=>`<button class="${detailTab===id?'active':''}" data-action="tab" data-tab="${id}">${label}</button>`).join('')}</nav><div id="detailBody">${detailBody()}</div></section></div><aside class="stack" style="align-content:start">${card('当前操作',`<div class="pad action-list">${recordActions(r)}</div>`)}${r.kind==='task'?card('费用明细',`<div class="pad"><div class="data-line"><small>项目总预算</small><strong>${money(d.budget)}</strong></div><div class="data-line"><small>服务费率</small><strong>${e(d.fee_rate)}%</strong></div><div class="data-line"><small>预计飞手收入</small><strong>${money(Number(d.budget)*(1-Number(d.fee_rate)/100))}</strong></div><div class="data-line"><small>收款核对</small><strong>${d.payment_received?'已登记':'尚未核对'}</strong></div><div class="data-line"><small>实际结算</small><strong>${d.settlement_ref?'已登记':'待结算'}</strong></div><p class="muted" style="font-size:11px;margin-top:15px">财务根据实际收付款凭证核对，网页操作不会自动转账。</p></div>`):''}${participant?card('业务协助',`<div class="pad"><p class="muted">遇到需求变更、交付争议或业务问题，可关联当前记录发起工单。</p>${btn('创建关联工单','new-ticket','small')}</div>`):''}</aside></div>`}
async function render(){const id=++renderToken;let raw=location.hash.slice(1)||'home';let route=raw.split('?')[0].split('/')[0];try{if(['home','login','register'].includes(route)){app.innerHTML=route==='home'?portal():authPage(route==='register');return}if(!session){sessionStorage.setItem('returnTo',raw);go('login');return}state=await api('/api/state');session=state.user;if(id!==renderToken)return;let html='';if(route==='overview')html=overview();else if(['orders','hall','compliance'].includes(route))html=ordersPage(route);else if(route==='new')html=newTask();else if(['equipment','devices','jobs','applications'].includes(route))html=listingPage(route);else if(route==='rentals')html=rentals();else if(route==='finance')html=finance();else if(route==='profile')html=await profilePage();else if(route==='users'){if(session.role!=='admin')throw Error('仅运营可访问');html=users()}else if(route==='notices')html=noticesPage();else if(route==='support')html=support();else if(route==='settings'){if(session.role!=='admin')throw Error('仅管理员可访问');html=settingsPage()}else if(route==='detail'){current=await api('/api/records/'+Number(raw.split('/')[1]));html=detailPage()}else{go('overview');return}if(id!==renderToken)return;app.innerHTML=shell(html,route);if(route==='new'){document.querySelector('[name=fee_preview]').readOnly=true;document.querySelector('[name=lat]').min='-90';document.querySelector('[name=lng]').min='-180';document.querySelector('[name=lat]').step='any';document.querySelector('[name=lng]').step='any'}document.title=(route==='detail'?current.record.data.title:'飞链协作平台')+' · FlyLink';}catch(err){if(id===renderToken)app.innerHTML=(session&&state?shell(`<div class="error-box"><h2>无法载入当前页面</h2><p>${e(err.message)}</p>${link('返回工作台','overview')}</div>`,route):`<div class="pad">${e(err.message)} ${link('返回登录','login')}</div>`)} }
function modal(title,content,submit,button='确认提交'){dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="dialog-close" data-action="close-modal" aria-label="关闭">×</button></div><div class="dialog-body"><form data-form="modal">${content}<div class="form-error" data-error></div><div class="dialog-foot">${btn('取消','close-modal')}<button class="btn primary">${button}</button></div></form></div>`;modalSubmit=submit;dialog.showModal()}
async function sendAction(action,extra={}){const r=current.record;await api('/api/records/'+r.id+'/action',{action,version:r.version,...extra});toast('操作已保存');await render()}
function actionModal(action){const r=current.record,d=r.data;let content='',title='',submit=x=>sendAction(action,x);if(action==='invoice'||action==='withdrawal'){title=action==='invoice'?'申请开票':'申请结算对账';content=field(action==='invoice'?'发票抬头':'申请标题','title')+area(action==='invoice'?'税号、发票类型与接收信息':'对账问题与联系信息','description');submit=x=>api('/api/records',{kind:action,parent:r.id,...x}).then(()=>{toast('申请已创建');render()})}
else if(action==='rent'){title='预约租赁设备';content=`<div class="notice">${e(d.title)} · 日租 ${money(d.daily_price)} · 押金 ${money(d.deposit)}。所选租期包含起止两日；提交后锁定该时段预约。</div><div class="form-grid">${field('开始日期','start','date')}${field('结束日期','end','date')}</div>${select('交付方式','delivery',['线下自提','物流配送'])}${area('交付地址与联系人','address')}`;submit=x=>api('/api/records',{kind:'rental',device:r.id,...x}).then(y=>{go('detail/'+y.record.id);toast('租赁预约已创建')})}
else if(action==='apply'){title='投递职业档案';content=area('应聘说明','cover','',false);submit=x=>api('/api/records',{kind:'application',job:r.id,...x}).then(y=>{go('detail/'+y.record.id);toast('已提交应聘申请')})}
else if(action==='review'){title='业务审核';content=select('审核结果','decision',[['approved','通过'],['rejected','退回补充']])+area('审核意见','note');submit=x=>sendAction(action,{...x,approved:x.decision==='approved'})}
else if(action==='gates'){title='核对作业条件';const g=d.gates||{};content=`<div class="notice">请先在文件区上传合规凭证。录入实际核验依据及机型限值；确认提交将记录核验人员和当前时间。</div><div class="form-grid">${field('航空器登记依据 / 编号','device_ref','text',g.device_ref)}${field('空域核验依据 / 回执号','airspace_ref','text',g.airspace_ref)}${select('空域条件结论','airspace',[['pending','待核实'],['approved','已有充分依据且满足条件'],['blocked','条件不满足']],g.airspace)}${select('降水是否影响作业','rain',[['yes','有影响 / 待核实'],['no','无影响']],g.rain)}${field('当前实测风速（m/s）','wind','number',g.wind??'')}${field('本机型本次作业风速上限（m/s）','wind_limit','number',g.wind_limit??'')}</div>${area('核验来源、适用范围与说明','note',g.note||'')}`}
else if(action==='payment'){title='核对实际付款';content=`<div class="notice">先上传“付款凭证”，再由财务核对实际到账。此操作仅登记账务结果。</div>${field('实际到账流水 / 凭证编号','reference')}${r.kind==='rental'?field('保险单号 / 保障依据','insurance_ref','text','',true,'先在文件区上传用途为“合规凭证”的租赁保险。'):''}`}
else if(action==='settle'){title='登记实际结算';content=`<div class="notice">请先上传实际结算凭证。项目 ${money(d.budget)}，平台费率 ${e(d.fee_rate)}%，飞手应收 ${money(Number(d.budget)*(1-Number(d.fee_rate)/100))}。</div>${field('实际打款流水 / 结算凭证号','reference')}${area('结算说明','note','',false)}`}
else if(action==='claim'){title='确认承接任务';content=`<p>${e(d.title)}</p><div class="notice">项目预算 ${money(d.budget)}，平台服务费 ${e(d.fee_rate)}%。承接前将再次检查五项作业条件。</div>${check('我已阅读作业要求、验收标准与费用，确认能力及设备满足本次任务。','checklist')}`;submit=x=>{if(!x.checklist)throw Error('请先确认任务要求');return sendAction(action)}}
else if(action==='start'){title='现场检查与开工作业';content=area('现场签到与检查记录','note','',true,'记录到场地点、检查结果及现场限制。')+check('已确认电量、机体、现场环境及飞行计划满足本次作业要求。','checklist')}
else if(action==='plan'){title='提交飞行计划';content=area('飞行区域、时段、高度、设备与风险措施','plan',d.plan||'')}
else if(action==='submit'){title='提交作业成果';content='<div class="notice">请先在“文件与成果”上传用途为“成果文件”的交付物。</div>'+area('交付内容与作业总结','report',d.report||'')}
else if(action==='accept'){title='确认成果验收';content=`<div class="notice"><b>约定验收标准</b><br>${e(d.acceptance)}</div>${area('验收结果与说明','note')}${check('已核对全部约定指标及交付文件，确认成果符合要求。','checklist')}`}
else if(action==='review_service'){title='履约评价';content=select('综合评分','rating',[[5,'5 分 · 非常满意'],[4,'4 分 · 满意'],[3,'3 分 · 一般'],[2,'2 分 · 需改进'],[1,'1 分 · 不满意']])+area('评价内容','note')}
else if(action==='reschedule'){title='调整执行时间';content=field('新的执行时间','execute_time','datetime-local')+area('改期原因与沟通结果','note')+'<div class="notice">改期后原作业条件核验失效，需要运营重新核实。</div>'}
else if(action==='cancel_confirm'){title='处理取消申请';content=area('责任、费用与处理说明','note')+(d.payment_received?field('实际退款流水号','reference')+'<div class="notice">请先上传退款凭证，再确认取消。</div>':'')}
else if(action==='inspect'){title='验机与押金结清';content=field('设备损坏扣款（元）','damage','number',0)+area('验机结果与定损依据','note')+field('押金退款 / 结清流水号','reference')+'<div class="notice">请先上传验机记录及押金退款凭证；金额为0时上传结清说明。</div>'}
else if(action==='sign'){title='确认合同内容';content='<div class="notice">请下载并阅读合同文件。此处记录双方对条款的确认，不代替具有认证签名的电子签约服务。</div>'+check('我已阅读本业务合同文件并确认内容。','checklist');submit=x=>{if(!x.checklist)throw Error('请确认合同内容');return sendAction(action)}}
else{title={release:'复核飞行准备',rework:'要求整改',pause:'异常上报并中止',resume:'复核恢复任务',cancel:'取消业务',return:'申请设备归还',interview:'发送面试安排',offer:'提交录用与合同',hire:'确认入职',reject:'结束应聘申请',process:'记录处理进展',resolve:'完成工单处理',toggle:'变更设备上架状态',close:'关闭招聘岗位',resubmit:'补充说明并重新提交'}[action]||'确认操作';content=area('处理说明','note','',!['toggle','close','hire'].includes(action));if(action==='offer')content='<div class="notice">请先上传用途为“合同文件”的附件，再提交录用信息。</div>'+content}
modal(title,content,submit)}
function newDevice(){modal('登记出租设备',`<div class="form-grid">${field('设备展示名称','title')}${field('型号','model')}${field('城市','city')}${field('实名登记编号','registration')}${field('日租金（元）','daily_price','number')}${field('押金（元）','deposit','number')}</div>${area('设备参数与适用范围','specs')}${area('配件清单','accessories')}${area('设备状态与补充说明','description','',false)}`,x=>api('/api/records',{kind:'device',...x}).then(r=>{go('detail/'+r.record.id);toast('已创建设备档案，请上传登记与维保凭证')}))}
function newJob(){modal('发布招聘岗位',field('岗位名称','title')+`<div class="form-grid">${field('工作城市','city')}${select('岗位类型','job_type',['全职','长期兼职'])}${field('月薪下限（元）','salary_min','number')}${field('月薪上限（元）','salary_max','number')}</div>`+select('执照要求','license',['CAAC-视距内','CAAC-超视距'])+area('职责、任职要求与福利','description'),x=>api('/api/records',{kind:'job',...x}).then(r=>{go('detail/'+r.record.id);toast('岗位已提交审核')}))}
function newTicket(){const r=location.hash.startsWith('#detail/')?current?.record:null;modal('创建服务工单',(r?`<div class="notice">关联业务：${e(r.number)} · ${e(r.data.title)}</div>`:'')+field('工单标题','title')+select('问题类型','category',['业务咨询','交付争议','退款与对账','设备问题','异常 / 事故报告','其他'])+area('问题说明、诉求与联系方式','description'),x=>api('/api/records',{kind:'ticket',parent:r?.id,...x}).then(y=>{go('detail/'+y.record.id);toast('工单已创建')}))}
async function reviewUser(id){const p=state.people.find(x=>x.id===Number(id));const f=await api('/api/users/'+id+'/files');const d=p.data;modal('用户资料与审核',`<div class="notice">${e(d.name||p.username)} · ${p.role==='pilot'?'飞手':'需求方'} · ${e(d.contact||'尚未填写联系方式')}</div><dl class="detail-meta">${[['城市',d.city],['主体编号',d.company_no],['执照',d.license],['执照有效期',d.license_expiry],['保险有效期',d.insurance_expiry],['保险单号',d.insurance_no],['机型与登记',`${d.device||''} / ${d.registration||''}`],['申请场景',(d.skills||[]).join('、')],['项目经历',d.projects],['简介',d.bio]].filter(x=>x[1]).map(([k,v])=>`<div><dt>${k}</dt><dd>${e(v)}</dd></div>`).join('')}</dl><h3 class="section-gap">认证文件</h3>${filesHTML(f.files)}${select('处理结果','decision',[['approved','认证通过并授予所列场景'],['rejected','退回补充材料'],['disable','停用账户'],['enable','启用账户并重新审核']])}${area('核验依据与审核意见','reason')}`,x=>api('/api/users/'+id+'/review',{...x,action:['disable','enable'].includes(x.decision)?x.decision:'review'}).then(()=>{toast('审核结果已保存');render()}))}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;event.preventDefault();const action=b.dataset.action;try{if(action==='close-modal'){dialog.close();return}if(action==='menu'){document.getElementById('sidebar').classList.toggle('open');return}if(action==='refresh'){await render();toast('数据已更新');return}if(action==='logout'){await api('/api/auth',{mode:'logout'});session=null;state=null;const s=await api('/api/session');csrf=s.csrf;go('login');return}if(action==='new-device')return newDevice();if(action==='new-job')return newJob();if(action==='new-ticket')return newTicket();if(action==='review-user')return await reviewUser(b.dataset.id);if(action==='record-action')return actionModal(b.dataset.do);if(action==='tab'){detailTab=b.dataset.tab;app.innerHTML=shell(detailPage(),'detail');return}if(action==='invite'){await sendAction('invite',{pilot:Number(b.dataset.id)});return}if(action==='read-all'){await api('/api/notices',{});await render();toast('全部标为已读');return}if(action==='notice'){await api('/api/notices',{id:Number(b.dataset.id)});if(b.dataset.record)go('detail/'+b.dataset.record);else await render();return}if(action==='online')return modal('接单状态',select('选择当前状态','online',[['idle','在线 · 接收符合条件的任务'],['busy','忙碌 · 暂不接收新任务'],['offline','休息 · 暂不接收新任务']],session.data.online),x=>api('/api/profile',{action:'online',...x}).then(()=>{toast('接单状态已更新');render()}));if(action==='password')return modal('修改登录密码',field('原密码','old','password')+field('新密码（至少10位）','password','password'),x=>api('/api/profile',{action:'password',...x}).then(()=>toast('密码已更新')))}catch(err){toast(err.message,true)}});
document.addEventListener('submit',async event=>{const f=event.target;if(!f.dataset.form)return;event.preventDefault();const error=f.querySelector('[data-error]');if(error)error.textContent='';const button=f.querySelector('button[type=submit],button:not([type]):not([data-action])');if(button)button.disabled=true;try{const d=formData(f),kind=f.dataset.form;if(kind==='auth'){const r=await api('/api/auth',d);session=r.user;csrf=r.csrf;const back=sessionStorage.getItem('returnTo');sessionStorage.removeItem('returnTo');go(back||'overview')}else if(kind==='new-task'){const r=await api('/api/records',{kind:'task',...d});detailTab='overview';go('detail/'+r.record.id);toast('需求已提交，请上传相关资料')}else if(kind==='modal'){await modalSubmit(d);dialog.close()}else if(kind==='profile'){d.skills=Array.from(f.querySelectorAll('[name=skill]:checked')).map(x=>x.value);await api('/api/profile',d);toast('资料已提交审核');await render()}else if(kind==='upload'){await api('/api/upload',new FormData(f));toast('文件已保存');await render()}else if(kind==='chat'){await sendAction('message',{text:d.text})}else if(kind==='config'){await api('/api/config',d);toast('配置已保存');await render()}}catch(err){if(error)error.textContent=err.message;else toast(err.message,true)}finally{if(button)button.disabled=false}});
function filter(){const q=(document.getElementById('search')?.value||'').toLowerCase(),s=document.getElementById('statusFilter')?.value||'';let count=0;document.querySelectorAll('[data-filter]').forEach(n=>{const yes=n.dataset.filter.toLowerCase().includes(q)&&(!s||n.dataset.status===s);n.classList.toggle('filter-hidden',!yes);if(yes)count++});const el=document.querySelector('.result-count');if(el)el.textContent='显示 '+count+' 条记录'}
document.addEventListener('input',ev=>{if(ev.target.id==='search')filter()});document.addEventListener('change',ev=>{if(ev.target.id==='statusFilter')filter()});
window.addEventListener('hashchange',()=>{detailTab='overview';render();window.scrollTo(0,0)});
async function init(){try{const s=await api('/api/session');session=s.user;csrf=s.csrf;await render()}catch(err){app.innerHTML=`<div class="loading"><h1>无法连接飞链服务</h1><p>${e(err.message)}</p><p>请解压完整软件包，运行“启动飞链.bat”，然后使用浏览器访问服务地址。</p></div>`}}
setInterval(async()=>{
 if(!session||!current||!location.hash.startsWith('#detail/')||document.hidden||dialog.open||document.activeElement?.closest('form'))return;
 try{const next=await api('/api/records/'+current.record.id);if(next.record.version!==current.record.version||next.events.length!==current.events.length||next.messages.length!==current.messages.length){current=next;await render();}}catch(_err){}
},10000);
init();
